  "dua.day.1.label": "قبل النوم",
  "dua.day.1.tr": "باسمك اللهم أموت وأحيا",
  "dua.day.1.en": "باسمك اللهم أموت وأحيا.",
  "dua.day.1.src": "صحيح البخاري",
