  "dua.day.2.tr": "بسم الله توكلت على الله ولا حول ولا قوة إلا بالله",
  "dua.day.2.en": "بسم الله توكلت على الله، ولا حول ولا قوة إلا بالله.",
  "dua.day.2.src": "سنن أبي داود · جامع الترمذي",
  "dua.day.3.label": "عند دخول البيت",
  "dua.day.3.tr": "بسم الله ولجنا وبسم الله خرجنا وعلى ربنا توكلنا",
  "dua.day.3.en": "بسم الله ولجنا، وبسم الله خرجنا، وعلى ربنا توكلنا.",
  "dua.day.3.src": "سنن أبي داود",
  "dua.day.4.label": "عند لبس ثوب جديد",
  "dua.day.4.tr": "الحمد لله الذي كساني هذا ورزقنيه من غير حول مني ولا قوة",
  "dua.day.4.en": "الحمد لله الذي كساني هذا ورزقنيه من غير حول مني ولا قوة.",
  "dua.day.4.src": "سنن أبي داود · جامع الترمذي",
  "dua.day.5.label": "عند النظر في المرآة",
  "dua.day.5.tr": "اللهم أنت حسّنت خلقي فحسّن خُلقي",
  "dua.day.5.en": "اللهم أنت حسّنت خلقي فحسّن خُلقي.",
  "dua.day.5.src": "مسند أحمد",
  "dua.food.title": "الطعام والشراب",
  "dua.food.0.label": "قبل الطعام",
